"""Fixed comfort cards in every language the check-in offers.

The backend owns these translations: GET /public-patients and the intake record
carry the cards already written in the patient's language, and the patient's
screen shows them as they come. A language (or one set) that is missing here
falls back to the English set, so a patient always gets 3 safe cards.

Card set names (exactly 3 cards each, every card is {"title", "instruction"}):
  esi1 .. esi5    by the visible ESI level
  crisis          suicidal thoughts at ESI 2 or more (988 line)
  child2, child   a young child at ESI 2, and at ESI 3 to 5 (written to the parent)
  needs_reading   the rules could not read the words and no AI translation was made

Each language lists its 20 distinct cards once (see _sets for which set uses
which card), so a shared card such as "wait to eat or drink" reads the same in
every set. Rules for every card (tests/test_comfort_i18n.py checks them all):
  * nothing by mouth until a nurse says it is OK, and no medicine,
  * every set tells the patient to tell staff (or names 988), in its own language,
  * never tell a waiting patient to leave,
  * no em or en dashes, short sentences a 12 year old can read, formal "you",
  * 911 and 988 stay as digits,
  * titles at most 40 characters, instructions at most 160.
Register: Chinese is Simplified, Portuguese is Brazilian, Bengali uses the
Bangladesh word for water; Arabic and Polish use "please" forms that avoid gender.
The cards other than English were drafted with AI help and have not yet been
reviewed by native speakers or medical interpreters.
"""
from __future__ import annotations

SET_NAMES: tuple[str, ...] = (
    "esi1", "esi2", "esi3", "esi4", "esi5", "crisis", "child2", "child", "needs_reading",
)
LANGUAGES: tuple[str, ...] = (
    "en", "es", "zh", "hi", "ar", "fr", "pt", "ru", "ja", "ko",
    "vi", "de", "it", "tr", "pl", "fa", "ur", "id", "tl", "bn",
)
CARD_KEYS: tuple[str, ...] = (
    "esi1_a", "esi1_b", "esi1_c", "esi2", "esi3", "esi4", "esi5", "npo", "ask", "worse", "stay",
    "crisis_a", "crisis_b", "crisis_c", "child2_a", "child2_c", "child_a", "child_c", "child_food", "needs_reading",
)


def _c(title: str, instruction: str) -> dict:
    return {"title": title, "instruction": instruction}


def _sets(**cards: tuple[str, str]) -> dict[str, list[dict]]:
    """The nine sets from one language's 20 cards (every key in CARD_KEYS, exactly)."""
    if set(cards) != set(CARD_KEYS):
        raise ValueError(f"comfort cards: wrong keys {sorted(set(cards) ^ set(CARD_KEYS))}")

    def pick(*keys: str) -> list[dict]:
        return [_c(*cards[k]) for k in keys]

    return {
        "esi1": pick("esi1_a", "esi1_b", "esi1_c"),
        "esi2": pick("esi2", "npo", "worse"),
        "esi3": pick("esi3", "npo", "worse"),
        "esi4": pick("esi4", "ask", "stay"),
        "esi5": pick("esi5", "ask", "stay"),
        "crisis": pick("crisis_a", "crisis_b", "crisis_c"),
        "child2": pick("child2_a", "child_food", "child2_c"),
        "child": pick("child_a", "child_food", "child_c"),
        "needs_reading": pick("needs_reading", "npo", "worse"),
    }


