def _valid(cards: object) -> bool:
    return (
        isinstance(cards, list) and len(cards) == 3
        and all(isinstance(c, dict) and str(c.get("title", "")).strip() and str(c.get("instruction", "")).strip()
                for c in cards)
    )


def cards_for(language: str | None, set_name: str) -> tuple[list[dict], str]:
    """(three cards, the language they are written in). English when this
    language or this set is not here."""
    lang = (language or "en").strip().lower().split("-")[0][:2] or "en"
    name = set_name if set_name in SET_NAMES else "esi3"
    cards = (COMFORT_CARDS.get(lang) or {}).get(name)
    if _valid(cards):
        return [dict(c) for c in cards], lang
    return [dict(c) for c in COMFORT_CARDS["en"][name]], "en"


def translated_languages() -> list[str]:
    """Languages with every set filled in (for the coverage check)."""
    return [lang for lang, sets in COMFORT_CARDS.items() if all(_valid(sets.get(n)) for n in SET_NAMES)]
